// Convert the query point to CGAL's kernel type
    const auto& cgal_p = CGAL::Point_3<typename Tree::Kernel>(p.x(), p.y(), p.z());

    // If the point is on the surface, consider it inside
    if (tree.do_intersect(cgal_p)) {
        return true;
    }

    // Generate random directions for ray casting
    std::vector<typename Tree::Kernel::Direction_3> directions;
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<> dis(-1.0, 1.0);

    for (int i = 0; i < numberOfChecks; ++i) {
        typename Tree::Kernel::FT x, y, z;
        do {
            x = dis(gen);
            y = dis(gen);
            z = dis(gen);
        } while (x == 0 && y == 0 && z == 0); // Ensure direction is not zero

        directions.emplace_back(x, y, z);
    }

    // Perform ray casting
    int intersections = 0;
    for (const auto& dir : directions) {
        typename Tree::Kernel::Ray_3 ray(cgal_p, dir);
        intersections += tree.number_of_intersected_primitives(ray);
    }

    // Point is inside if odd number of intersections on average
    return (intersections % (2 * numberOfChecks)) >= numberOfChecks;
    // END_CODE

